# ---------------- embedded bitmap fonts ----------------
# FONT_BLOB: base64(zlib(json)) ; json: {"<family>:<size>": {char: {a,l,t,w,h,rows}}}
# a=advance, l=left bearing, t=top offset from baseline, w/h bitmap size,
# rows=base64 packed bits, MSB first, row stride (w+7)//8.
_FONTS = None


def load_fonts():
    global _FONTS
    if _FONTS is not None:
        return _FONTS
    raw = json.loads(zlib.decompress(bytes.fromhex(FONT_BLOB)).decode("utf-8"))
    fonts = {}
    for key, glyphs in raw.items():
        fam, size = key.split(":")
        dec = {}
        for ch, g in glyphs.items():
            dec[ch] = (g["a"], g["l"], g["t"], g["w"], g["h"],
                       base64.b64decode(g["rows"]))
        fonts[(fam, int(size))] = dec
    _FONTS = fonts
    return fonts


def glyph(fam, size, ch):
    f = load_fonts()[(fam, size)]
    g = f.get(ch)
    if g is None:
        g = f["?"]
    return g


def text_width(fam, size, text):
    return sum(glyph(fam, size, ch)[0] for ch in text)


def text_ink(fam, size, text):
    """(ink_left_offset, ink_width) of the string relative to pen x."""
    if not text:
        return 0, 0
    w = text_width(fam, size, text)
    first = glyph(fam, size, text[0])
    last = glyph(fam, size, text[-1])
    left = first[1]
    right = (w - last[0]) + last[1] + last[3]
    return left, right - left


# ---------------- pixel buffer + primitives ----------------
BUF = bytearray(W * H * 3)


def set_px(x, y, c):
    if 0 <= x < W and 0 <= y < H:
        i = (y * W + x) * 3
        BUF[i] = c[0]
        BUF[i + 1] = c[1]
        BUF[i + 2] = c[2]


def get_px(x, y):
    if 0 <= x < W and 0 <= y < H:
        i = (y * W + x) * 3
        return (BUF[i], BUF[i + 1], BUF[i + 2])
    return None


def fill_rect(x, y, w, h, c):
    x0 = max(0, x)
    y0 = max(0, y)
    x1 = min(W, x + w)
    y1 = min(H, y + h)
    for yy in range(y0, y1):
        base = (yy * W + x0) * 3
        for xx in range(x0, x1):
            i = base + (xx - x0) * 3
            BUF[i] = c[0]
            BUF[i + 1] = c[1]
            BUF[i + 2] = c[2]


def rect_border(x, y, w, h, c, t=2):
    fill_rect(x, y, w, t, c)
    fill_rect(x, y + h - t, w, t, c)
    fill_rect(x, y, t, h, c)
    fill_rect(x + w - t, y, t, h, c)


def hline(x0, x1, y, c):
    if x0 > x1:
        x0, x1 = x1, x0
    for x in range(x0, x1 + 1):
        set_px(x, y, c)


def vline(x, y0, y1, c):
    if y0 > y1:
        y0, y1 = y1, y0
    for y in range(y0, y1 + 1):
        set_px(x, y, c)


def disc(cx, cy, r, c):
    if r <= 0:
        set_px(cx, cy, c)
        return
    for dy in range(-r, r + 1):
        dx = int(math.sqrt(r * r - dy * dy))
        hline(cx - dx, cx + dx, cy + dy, c)


def ring(cx, cy, r, c, t=1):
    for dy in range(-r - 1, r + 2):
        for dx in range(-r - 1, r + 2):
            d = math.sqrt(dx * dx + dy * dy)
            if r - t < d <= r:
                set_px(cx + dx, cy + dy, c)


def ellipse(cx, cy, rx, ry, c):
    if rx <= 0 or ry <= 0:
        return
    for dy in range(-ry, ry + 1):
        dx = int(rx * math.sqrt(max(0.0, 1.0 - (dy * dy) / float(ry * ry))))
        hline(cx - dx, cx + dx, cy + dy, c)


def line(x0, y0, x1, y1, c, thick=1):
    steps = max(abs(x1 - x0), abs(y1 - y0), 1)
    r = thick // 2
    for i in range(steps + 1):
        t = i / float(steps)
        x = int(round(x0 + (x1 - x0) * t))
        y = int(round(y0 + (y1 - y0) * t))
        if thick <= 1:
            set_px(x, y, c)
        else:
            disc(x, y, r, c)


def poly(points, c):
    """Scanline fill of a polygon (list of (x, y))."""
    if len(points) < 3:
        return
    ys = [p[1] for p in points]
    for y in range(min(ys), max(ys) + 1):
        xs = []
        n = len(points)
        for i in range(n):
            x0, y0 = points[i]
            x1, y1 = points[(i + 1) % n]
            if (y0 <= y < y1) or (y1 <= y < y0):
                x = x0 + (y - y0) * (x1 - x0) / float(y1 - y0)
                xs.append(x)
        xs.sort()
        for i in range(0, len(xs) - 1, 2):
            hline(int(math.ceil(xs[i])), int(math.floor(xs[i + 1])), y, c)


def arc_pts(cx, cy, r, a0, a1, ry_scale=1.0):
    pts = []
    n = max(8, int(abs(a1 - a0) * r / 4) + 1)
    for i in range(n + 1):
        a = a0 + (a1 - a0) * i / float(n)
        pts.append((cx + r * math.cos(a), cy + r * math.sin(a) * ry_scale))
    return pts


def arc_line(cx, cy, r, a0, a1, c, thick=1, ry_scale=1.0):
    pts = arc_pts(cx, cy, r, a0, a1, ry_scale)
    for i in range(len(pts) - 1):
        line(int(round(pts[i][0])), int(round(pts[i][1])),
             int(round(pts[i + 1][0])), int(round(pts[i + 1][1])), c, thick)


def draw_text(x, y_base, fam, size, text, color):
    """Draw text with pen at x, baseline y_base. Returns end pen x."""
    pen = x
    for ch in text:
        adv, left, top, w, h, rows = glyph(fam, size, ch)
        if w and h:
            rb = (w + 7) // 8
            for r in range(h):
                yy = y_base + top + r
                if yy < 0 or yy >= H:
                    continue
                row = rows[r * rb:(r + 1) * rb]
                for col in range(w):
                    if row[col >> 3] & (0x80 >> (col & 7)):
                        set_px(pen + left + col, yy, color)
        pen += adv
    return pen


def draw_text_center(cx, y_base, fam, size, text, color):
    w = text_width(fam, size, text)
    return draw_text(cx - w // 2, y_base, fam, size, text, color)


# ---------------- word wrap ----------------
def wrap(text, fam, size, max_w):
    words = text.split(" ")
    lines = []
    cur = ""
    for wd in words:
        trial = wd if not cur else cur + " " + wd
        if text_width(fam, size, trial) <= max_w or not cur:
            cur = trial
        else:
            lines.append(cur)
            cur = wd
    if cur:
        lines.append(cur)
    return lines


def wrap_no_orphan(text, fam, size, max_w):
    """Greedy wrap, then fix a single-word last line by pulling a word down."""
    lines = wrap(text, fam, size, max_w)
    while len(lines) >= 2 and len(lines[-1].split(" ")) == 1:
        prev_words = lines[-2].split(" ")
        if len(prev_words) <= 1:
            break
        moved = prev_words[-1]
        new_last = moved + " " + lines[-1]
        if text_width(fam, size, new_last) > max_w:
            break
        lines[-2] = " ".join(prev_words[:-1])
        lines[-1] = new_last
    return lines

