# ---------------- scenes ----------------
# Every scene: ground fill + motif + 2px BORDER #6B8AB5 (drawn last, on top).
# Banner chip: red #B01E1E, white bold text, top-left inside the scene
# (lead 03 chart: bottom-left, so the falling line keeps the full width).

def scene_frame(x, y, w, h, ground):
    fill_rect(x, y, w, h, ground)
    return (x, y, w, h)


def banner(x, y, text, size):
    tw = text_width("sans_b", size, text)
    pad_x, pad_y = 7, 5
    bw, bh = tw + pad_x * 2, size + pad_y * 2 + 2
    fill_rect(x, y, bw, bh, RED_CHIP)
    draw_text(x + pad_x, y + pad_y + size - 2, "sans_b", size, text, WHITE)
    return (x, y, bw, bh)


def face(cx, cy, r, skin=(232, 184, 138)):
    """Head circle with dot eyes + mouth. r ~ head radius."""
    disc(cx, cy, r, skin)
    eye = (20, 20, 30)
    set_px(cx - r // 3, cy - 1, eye)
    set_px(cx + r // 3, cy - 1, eye)
    hline(cx - r // 3, cx + r // 3, cy + r // 2, eye)


def figure(x, y, h, body, skin=(232, 184, 138), with_face=True):
    """Standing figure, feet at (x, y), total height h."""
    hr = max(3, h // 5)
    disc(x, y - h + hr, hr, skin)
    if with_face:
        eye = (20, 20, 30)
        set_px(x - hr // 3, y - h + hr - 1, eye)
        set_px(x + hr // 3, y - h + hr - 1, eye)
        hline(x - hr // 3, x + hr // 3, y - h + hr + hr // 2, eye)
    fill_rect(x - h // 8, y - h + 2 * hr, h // 4, h - 2 * hr - 2, body)
    line(x - 1, y - 2, x - 3, y, INK, 2)
    line(x + 1, y - 2, x + 3, y, INK, 2)


def scene_cyclone(x, y, w, h):
    scene_frame(x, y, w, h, (11, 42, 58))
    # rain hatching, upper left
    for i in range(16):
        rx = x + 12 + i * 19
        line(rx, y + 10, rx - 6, y + 22, (110, 147, 168), 1)
        line(rx + 8, y + 30, rx + 2, y + 42, (110, 147, 168), 1)
    # whole spiral, never sliced: centre right, max radius 46
    cx, cy = x + 205, y + 62
    for k, col in enumerate(((220, 239, 247), (143, 195, 220), (94, 147, 181))):
        ph = k * 2.094
        pts = []
        th = 0.0
        while th < 4.4 * math.pi:
            r = 5 + th * 3.1
            pts.append((cx + r * math.cos(th + ph), cy + r * math.sin(th + ph) * 0.82))
            th += 0.16
        for i in range(len(pts) - 1):
            line(int(pts[i][0]), int(pts[i][1]), int(pts[i + 1][0]),
                 int(pts[i + 1][1]), col, 3)
    disc(cx, cy, 6, (11, 42, 58))
    ring(cx, cy, 7, (220, 239, 247), 1)
    # small house, bottom left
    hx, hy = x + 16, y + h - 34
    fill_rect(hx, hy, 34, 22, (216, 196, 154))
    poly([(hx - 4, hy), (hx + 17, hy - 14), (hx + 38, hy)], (140, 74, 47))
    fill_rect(hx + 13, hy + 10, 8, 12, (60, 40, 26))
    # evacuee figures with faces, bottom centre
    for fx, col in ((x + 128, (229, 87, 46)), (x + 158, (255, 209, 102)),
                    (x + 188, (42, 157, 143))):
        figure(fx, y + h - 8, 30, col)
    # umbrella over first figure
    arc_line(x + 128, y + h - 34, 12, math.pi, 2 * math.pi, (220, 239, 247), 2)
    line(x + 128, y + h - 34, x + 128, y + h - 12, (220, 239, 247), 1)
    return banner(x + 6, y + 6, "CYCLONE", 30)


def scene_kyiv(x, y, w, h):
    scene_frame(x, y, w, h, (10, 15, 26))
    # stars + city lights
    for sx, sy in ((30, 12), (70, 22), (150, 10), (210, 18), (280, 12), (120, 26)):
        set_px(x + sx, y + sy, PALE)
    for lx in range(14, 310, 18):
        disc(x + lx, y + 66, 1, GOLD)
    # river
    fill_rect(x, y + 96, w, h - 96, (16, 39, 63))
    for rx in range(20, 300, 26):
        hline(x + rx, x + rx + 12, y + 104, (90, 130, 170))
        hline(x + rx + 6, x + rx + 16, y + 114, (70, 105, 145))
    # bridge: deck, two arches, piers
    deck_y = y + 76
    line(x + 6, deck_y, x + w - 6, deck_y, (138, 151, 164), 3)
    arc_line(x + 92, deck_y, 44, math.pi, 2 * math.pi, (170, 182, 196), 3)
    arc_line(x + 228, deck_y, 44, math.pi, 2 * math.pi, (170, 182, 196), 3)
    for px in (48, 136, 184, 272):
        line(x + px, deck_y, x + px, y + 112, (110, 123, 140), 3)
    # charred arch ends + scorch marks
    disc(x + 50, deck_y - 6, 7, (5, 7, 12))
    disc(x + 270, deck_y - 6, 7, (5, 7, 12))
    line(x + 52, deck_y - 12, x + 60, deck_y + 2, (58, 42, 26), 3)
    line(x + 268, deck_y - 12, x + 260, deck_y + 2, (58, 42, 26), 3)
    # flame tongues on the deck
    for fx in (120, 200, 250):
        poly([(x + fx - 6, deck_y), (x + fx, deck_y - 16), (x + fx + 6, deck_y)],
             (240, 138, 29))
        poly([(x + fx - 3, deck_y), (x + fx, deck_y - 8), (x + fx + 3, deck_y)],
             (255, 209, 102))
    # smoke columns
    for sx, sy in ((120, 52), (120, 38), (120, 26), (250, 54), (250, 42)):
        disc(x + sx, y + sy, 5, (90, 100, 112))
    # missile trails
    line(x + 252, y + 4, x + 212, y + 58, (255, 243, 196), 2)
    line(x + 58, y + 2, x + 94, y + 54, (255, 243, 196), 2)
    disc(x + 212, y + 58, 3, (255, 243, 196))
    disc(x + 94, y + 54, 3, (255, 243, 196))
    return banner(x + 6, y + 6, "BARRAGE", 30)


def scene_chart(x, y, w, h):
    scene_frame(x, y, w, h, (14, 30, 51))
    for gy in range(y + 22, y + h, 22):
        hline(x + 8, x + w - 8, gy, (30, 58, 86))
    # banner TOP-LEFT now: the ascending line occupies the bottom-left
    # corner, so the bottom-left chip would bury the Taipei point, its dot
    # and its label. Top-left is empty (the line starts at y+106).
    brect = banner(x + 6, y + 6, "SELL-OFF", 30)
    # Values on a LINEAR y scale: most negative = lowest on the page.
    # -6.2% .. -1.9% maps to y+106 .. y+30, so the line ASCENDS left to
    # right: Taipei (-6.2%) lowest, Seoul (-5.2%), Tokyo (-5.1%),
    # Hong Kong (-1.9%, the smallest drop) highest. The y range stops at
    # y+30 so the HONG KONG label still fits above its point inside the scene.
    vals = [-6.2, -5.2, -5.1, -1.9]
    v_lo, v_hi = min(vals), max(vals)

    def chart_y(v):
        return y + 30 + int(round((v_hi - v) / (v_hi - v_lo) * 76))

    pts = [(x + 26, chart_y(v_lo)), (x + 96, chart_y(vals[0])),
           (x + 162, chart_y(vals[1])), (x + 226, chart_y(vals[2])),
           (x + 292, chart_y(vals[3]))]
    # the plotted span must equal the full mapped range, and each labelled
    # point must sit at its linear-map height (within 1px of rounding)
    check("chart span 76px", pts[1][1] - pts[4][1] == 76,
          "Taipei y=%d HK y=%d" % (pts[1][1], pts[4][1]))
    check("chart Seoul offset", 57 <= pts[2][1] - pts[4][1] <= 60,
          "%d" % (pts[2][1] - pts[4][1]))
    check("chart Tokyo offset", 55 <= pts[3][1] - pts[4][1] <= 58,
          "%d" % (pts[3][1] - pts[4][1]))
    check("chart ascends left to right",
          all(pts[i][1] > pts[i + 1][1] for i in range(1, 4)),
          "ys=%r" % ([p[1] - y for p in pts[1:]],))
    for i in range(len(pts) - 1):
        line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], (229, 72, 77), 3)
    # pixel check: the red line must pass through the midpoints of each
    # segment at the linearly interpolated height (within 3px). Runs after
    # the banner is drawn, so it verifies the FINAL visible pixels.
    for (x0, y0), (x1, y1) in zip(pts[1:], pts[2:]):
        mx, my = (x0 + x1) // 2, (y0 + y1) // 2
        hit = any(get_px(mx, yy) == (229, 72, 77)
                  for yy in range(my - 3, my + 4))
        check("chart red at mid x=%d" % mx, hit, "expected y~%d" % my)
    # Labels: Taipei/Seoul/Hong Kong above their points; Tokyo BELOW its
    # point - Seoul (-5.2%) and Tokyo (-5.1%) sit 1px apart vertically, so
    # two above-labels on the same row would run together (same defect
    # class as H1). Below its point Tokyo's label clears the steeply
    # rising line to Hong Kong.
    labels = [("TAIPEI -6.2%", 1, -16), ("SEOUL -5.2%", 2, -16),
              ("TOKYO -5.1%", 3, +16), ("HONG KONG -1.9%", 4, -16)]
    boxes = []
    for text, idx, dy in labels:
        px, py = pts[idx]
        tw = text_width("sans_b", 10, text)
        lx = px - tw // 2
        lx = max(x + 4, min(lx, x + w - tw - 4))
        # 10px label ink spans baseline-8 .. baseline
        boxes.append((lx, py + dy - 8, lx + tw, py + dy))
    for i in range(len(boxes)):
        for j in range(i + 1, len(boxes)):
            a, b = boxes[i], boxes[j]
            overlap = not (a[2] <= b[0] or b[2] <= a[0] or
                           a[3] <= b[1] or b[3] <= a[1])
            check("chart labels %d-%d disjoint" % (i + 1, j + 1), not overlap,
                  "%r vs %r" % (a, b))
    bx, by, bw, bh = brect
    for i, (text, idx, dy) in enumerate(labels):
        px, py = pts[idx]
        check("banner clears point %d" % (i + 1),
              not (bx <= px <= bx + bw and by <= py <= by + bh),
              "point (%d,%d) inside chip" % (px - x, py - y))
        a = boxes[i]
        overlap = not (a[2] <= bx or bx + bw <= a[0] or
                       a[3] <= by or by + bh <= a[1])
        check("banner clears label %d" % (i + 1), not overlap, "%r" % (a,))
    for text, idx, dy in labels:
        px, py = pts[idx]
        disc(px, py, 4, GOLD)
        ring(px, py, 4, (255, 255, 255), 1)
        lx = px - text_width("sans_b", 10, text) // 2
        lx = max(x + 4, min(lx, x + w - text_width("sans_b", 10, text) - 4))
        draw_text(lx, py + dy, "sans_b", 10, text, WHITE)
    disc(pts[0][0], pts[0][1], 4, GOLD)
    poly([(x + 292, y + 30), (x + 282, y + 40), (x + 302, y + 38)], (229, 72, 77))
    return brect


