# ---------------- layout ----------------
MX = 24                      # side margin
CW = W - 2 * MX              # 976 content width
LEAD_SCENE_H = 120
TILE_SCENE_H = 66
LEAD_HEAD_LH = 26            # 24px serif bold
TILE_HEAD_LH = 22            # 20px serif bold
LEAD_DECK_LH = 14            # 13px serif
TILE_DECK_LH = 14            # 13px serif
BRIEF_PITCH = 15             # 11px type, 15px pitch

LAYOUT = {}                  # band name -> (y0, y1), for asserts + reporting
CHECKS = []                  # (name, ok, detail) recorded by asserts


def note(name, y0, y1):
    LAYOUT[name] = (y0, y1)


def check(name, ok, detail=""):
    CHECKS.append((name, bool(ok), detail))
    if not ok:
        raise AssertionError("CHECK FAILED: %s %s" % (name, detail))


def draw_strip(x, y_base, item, max_w):
    """Uniform 10px sans bold strip: gold number + pale ' · PLACE · CATEGORY'."""
    num = item["num"] + " "
    rest = "\u00b7 " + item["place"] + " \u00b7 " + item["cat"]
    w = text_width("sans_b", 10, num + rest)
    check("strip fits %s" % item["num"], w <= max_w,
          "w=%d max=%d" % (w, max_w))
    draw_text(x, y_base, "sans_b", 10, num, GOLD)
    draw_text(x + text_width("sans_b", 10, num), y_base, "sans_b", 10, rest, PALE)


def draw_headline_deck(x, y_top, col_w, item, head_size, head_lh, deck_lh):
    """Headline (serif bold, 2 lines max, no single-word last line) + deck.
    Returns y just below the deck ink."""
    lines = wrap_no_orphan(item["headline"], "serif_b", head_size, col_w)
    check("headline lines %s" % item["num"], 1 <= len(lines) <= 2,
          "%r -> %d lines" % (item["headline"], len(lines)))
    check("headline no orphan %s" % item["num"],
          len(lines) == 1 or len(lines[-1].split(" ")) >= 2,
          "%r" % (lines[-1],))
    y = y_top
    for ln in lines:
        y += head_lh
        draw_text(x, y - (head_lh - head_size) // 2 - 2, "serif_b", head_size, ln, CREAM)
    head_bottom = y
    dlines = wrap(item["deck"], "serif", 13, col_w)
    check("deck rejoin %s" % item["num"], " ".join(dlines) == item["deck"],
          "%r" % (item["deck"],))
    check("deck lines %s" % item["num"], len(dlines) <= 4,
          "%d lines" % len(dlines))
    for ln in dlines:
        y += deck_lh
        draw_text(x, y - 2, "serif", 13, ln, NEARWHITE)
    LAYOUT["deck_%s" % item["num"]] = (head_bottom, y)
    return y + 4  # ink bottom (+1) so the next band clears deck glyphs by >=4px


def render():
    fill_rect(0, 0, W, H, PAGE)
    load_fonts()

    # ---- kicker ----
    y_base = 18
    draw_text(MX, y_base, "sans_b", 11, KICKER_L, CREAM)
    rw = text_width("sans_b", 11, KICKER_R)
    draw_text(MX + CW - rw, y_base, "sans_b", 11, KICKER_R, GOLD)
    note("kicker", 10, 18)

    # ---- masthead ----
    # 68px serif bold -> cap height 52px (brief: ~51px). No rule under it:
    # the 'y' descender in "Friday" would cross a rule placed in the gap.
    m_base = 72
    draw_text(MX, m_base, "serif_b", 68, MASTHEAD, CREAM)
    # measure cap height from the ink of the masthead string
    ink_top = 10 ** 9
    ink_bot = -1
    pen = MX
    for ch in MASTHEAD:
        adv, left, top, w, h, _rows = glyph("serif_b", 68, ch)
        if w and h:
            ink_top = min(ink_top, m_base + top)
            ink_bot = max(ink_bot, m_base + top + h)
        pen += adv
    cap_h = m_base - ink_top  # cap top to baseline (no descender in cap letters)
    check("masthead cap height ~51", 48 <= cap_h <= 54, "cap=%d" % cap_h)
    note("masthead", ink_top, ink_bot)

    # ---- tagline ----
    t_base = 104
    draw_text(MX, t_base, "serif_i", 16, TAGLINE, PALE)
    check("tagline fits", text_width("serif_i", 16, TAGLINE) <= CW,
          "w=%d" % text_width("serif_i", 16, TAGLINE))
    note("tagline", 96, 112)

    # ---- stats ----
    stat_w = CW // 6
    bar_y = 114
    for i, st in enumerate(STATS):
        sx = MX + i * stat_w
        fill_rect(sx + 2, bar_y, stat_w - 10, 4, st["bar"])
        draw_text(sx + 2, 142, "sans_b", 26, st["value"], GOLD)
        cap = st["caption"]
        check("stat caption fits", text_width("sans_b", 9, cap) <= stat_w - 2,
              "%r w=%d" % (cap, text_width("sans_b", 9, cap)))
        draw_text(sx + 2, 158, "sans_b", 9, cap, PALE)
    # pixel clearance between adjacent stat captions (H1): scan the
    # caption band (baseline 158, 9px) for PALE ink per cell and require
    # >=5px of empty columns between neighbouring captions' ink.
    cap_ink = []
    for i in range(len(STATS)):
        sx = MX + i * stat_w
        xs = [xx for xx in range(sx, min(W, sx + stat_w))
              for yy in range(148, 169) if get_px(xx, yy) == PALE]
        cap_ink.append((min(xs), max(xs)) if xs else (None, None))
    for i in range(len(cap_ink) - 1):
        gap = cap_ink[i + 1][0] - cap_ink[i][1] - 1
        check("stat caption clearance %d-%d" % (i + 1, i + 2), gap >= 5,
              "gap=%d px (%r ink %d..%d, %r ink %d..%d)"
              % (gap, STATS[i]["caption"], cap_ink[i][0], cap_ink[i][1],
                 STATS[i + 1]["caption"], cap_ink[i + 1][0], cap_ink[i + 1][1]))
    note("stats", bar_y, 161)

    # ---- region bar (computed per item from the data, never hardcoded) ----
    all_items = LEADS + TILES + BRIEFS
    counts = {}
    for it in all_items:
        counts[it["region"]] = counts.get(it["region"], 0) + 1
    expected = {"Asia": 10, "Europe": 12, "Middle East": 1, "Africa": 3,
                "North America": 6, "Oceania": 3}
    check("region sums", counts == expected, "got %r" % (counts,))
    check("region total 35", sum(counts.values()) == 35, "%d" % sum(counts.values()))
    check("story count 35", len(all_items) == 35, "%d" % len(all_items))
    check("numbering 01-35 continuous",
          [it["num"] for it in all_items] == ["%02d" % n for n in range(1, 36)],
          "order/numbering mismatch")
    # largest-remainder widths summing exactly to CW
    raw = [(counts[r] / 35.0) * CW for r in REGION_ORDER]
    widths = [int(math.floor(v)) for v in raw]
    rem = CW - sum(widths)
    order = sorted(range(len(raw)), key=lambda i: raw[i] - widths[i], reverse=True)
    for i in range(rem):
        widths[order[i % len(order)]] += 1
    # min-width bump: a segment must fit its label + 6px; take pixels from
    # the widest segment (widths stay computed from the counts, only the
    # rounding slack moves).
    for i, r in enumerate(REGION_ORDER):
        need = text_width("sans_b", 9, "%s %d" % (REGION_LABELS[r], counts[r])) + 6
        if widths[i] < need:
            widest = widths.index(max(widths))
            take = need - widths[i]
            widths[widest] -= take
            widths[i] += take
    reg_y, reg_h = 168, 20
    rx = MX
    for r, wd in zip(REGION_ORDER, widths):
        fill_rect(rx, reg_y, wd, reg_h, REGION_COLORS[r])
        lab = "%s %d" % (REGION_LABELS[r], counts[r])
        check("region label fits %s" % r,
              text_width("sans_b", 9, lab) <= wd - 4,
              "%r w=%d seg=%d" % (lab, text_width("sans_b", 9, lab), wd))
        draw_text(rx + (wd - text_width("sans_b", 9, lab)) // 2, reg_y + 14,
                  "sans_b", 9, lab, WHITE)
        rx += wd
    check("region bar width", rx - MX == CW, "%d" % (rx - MX))
    note("region bar", reg_y, reg_y + reg_h)

    # ---- leads ----
    lead_w = (CW - 2 * 8) // 3
    strip_base = 202
    scene_y = 208
    for i, lead in enumerate(LEADS):
        lx = MX + i * (lead_w + 8)
        draw_strip(lx, strip_base, lead, lead_w)
        SCENES[lead["scene"]](lx, scene_y, lead_w, LEAD_SCENE_H)
        rect_border(lx, scene_y, lead_w, LEAD_SCENE_H, BORDER, 2)
        SCENE_GROUNDS["lead_" + lead["num"]] = LEAD_GROUNDS[lead["scene"]]
        y_end = draw_headline_deck(lx, scene_y + LEAD_SCENE_H + 4, lead_w, lead,
                                   24, LEAD_HEAD_LH, LEAD_DECK_LH)
        LAYOUT["lead_%s" % lead["num"]] = (strip_base - 10, y_end)
    leads_end = max(LAYOUT["lead_%s" % l["num"]][1] for l in LEADS)
    note("leads", strip_base - 10, leads_end)

    # ---- tiles, 2 rows x 5 ----
    tile_w = (CW - 4 * 8) // 5
    row_gap = 6
    tiles_end = leads_end
    for row in range(2):
        tstrip = tiles_end + 12
        tscene = tstrip + 6
        row_end = tscene
        for col in range(5):
            tile = TILES[row * 5 + col]
            tx = MX + col * (tile_w + 8)
            draw_strip(tx, tstrip, tile, tile_w)
            SCENES[tile["scene"]](tx, tscene, tile_w, TILE_SCENE_H)
            rect_border(tx, tscene, tile_w, TILE_SCENE_H, BORDER, 2)
            SCENE_RECTS["tile_" + tile["num"]] = (tx, tscene, tile_w, TILE_SCENE_H)
            SCENE_GROUNDS["tile_" + tile["num"]] = tile["ground"]
            y_end = draw_headline_deck(tx, tscene + TILE_SCENE_H + 3, tile_w, tile,
                                       20, TILE_HEAD_LH, TILE_DECK_LH)
            row_end = max(row_end, y_end)
        tiles_end = row_end + row_gap
        note("tiles row %d" % (row + 1), tstrip - 10, row_end)
    tiles_end -= row_gap
    note("tiles", LAYOUT["tiles row 1"][0], tiles_end)

    # ---- briefs: header + 3 balanced columns ----
    bh_base = tiles_end + 12
    draw_text(MX, bh_base, "sans_b", 12, BRIEFS_HEAD, CREAM)
    fill_rect(MX, bh_base + 5, CW, 1, GOLD)
    first_base = bh_base + 20
    # wrap each brief, then balance columns by line count (greedy shortest)
    wrapped = []
    for b in BRIEFS:
        num_w = text_width("sans_b", 11, b["num"] + " ")
        lines = wrap(b["text"], "sans", 11, (CW - 2 * 16) // 3 - num_w)
        check("brief lines %s" % b["num"], len(lines) <= 2,
              "%d lines" % len(lines))
        wc = len(b["text"].split(" "))
        check("brief words %s" % b["num"], 8 <= wc <= 12, "%d words" % wc)
        wrapped.append((b, lines))
    cols = [[], [], []]
    col_lines = [0, 0, 0]
    for b, lines in wrapped:
        c = col_lines.index(min(col_lines))
        cols[c].append((b, lines))
        col_lines[c] += len(lines)
    check("brief columns balanced", max(col_lines) - min(col_lines) <= 1,
          "lines per col %r" % (col_lines,))
    col_w = (CW - 2 * 16) // 3
    briefs_end = first_base
    for ci, col in enumerate(cols):
        cx = MX + ci * (col_w + 16)
        y = first_base
        for b, lines in col:
            for li, ln in enumerate(lines):
                if li == 0:
                    draw_text(cx, y, "sans_b", 11, b["num"], GOLD)
                    draw_text(cx + text_width("sans_b", 11, b["num"] + " "),
                              y, "sans", 11, ln, NEARWHITE)
                else:
                    draw_text(cx + text_width("sans_b", 11, b["num"] + " "),
                              y, "sans", 11, ln, NEARWHITE)
                y += BRIEF_PITCH
        briefs_end = max(briefs_end, y - BRIEF_PITCH + 11)
    note("briefs", bh_base - 12, briefs_end)

    # ---- DATE CHECK box, sized to its content ----
    dc_lines = wrap(DATE_CHECK, "sans_b", 11, CW - 16)
    dc_lh = 14
    dc_top = briefs_end + 3
    dc_h = 6 + len(dc_lines) * dc_lh + 4
    fill_rect(MX, dc_top, CW, dc_h, RED_BOX)
    y = dc_top + 6
    last_base = None
    for ln in dc_lines:
        y += dc_lh
        draw_text(MX + 8, y - 2, "sans_b", 11, ln, CREAM)
        last_base = y - 2
    # empty space below the last text line must be <= 5px
    descent = 0
    for ch in dc_lines[-1]:
        _a, _l, top, _w, h, _r = glyph("sans_b", 11, ch)
        descent = max(descent, top + h)
    empty_below = (dc_top + dc_h) - (last_base + descent)
    check("date check tight", empty_below <= 5, "empty=%d" % empty_below)
    note("date check", dc_top, dc_top + dc_h)

    # ---- footer ----
    # 11px, not 10px: the 10px comma loses its tail at threshold 64
    # (glyph audit); 11px keeps a diagonal descender tail.
    f_base = dc_top + dc_h + 10
    draw_text(MX, f_base, "sans", 11, FOOT_STATEMENT, FOOT)
    src_lines = wrap(FOOT_SOURCES, "sans", 11, CW)
    y = f_base
    for ln in src_lines:
        y += 13
        draw_text(MX, y, "sans", 11, ln, FOOT)
    foot_bottom = y
    for ch in src_lines[-1]:
        _a, _l, top, _w, h, _r = glyph("sans", 11, ch)
        foot_bottom = max(foot_bottom, y + top + h)
    check("footer clearance >=5px", foot_bottom <= 1019, "bottom=%d" % foot_bottom)
    check("final y <= 1020", foot_bottom <= 1020, "bottom=%d" % foot_bottom)
    note("footer", f_base - 10, foot_bottom)
    # no motif may bleed past its scene's bottom edge: the 3 rows below
    # every scene rect must contain no pixel of that scene's ground colour
    for key, (sx, sy, sw, sh) in SCENE_RECTS.items():
        g = SCENE_GROUNDS[key]
        leaked = 0
        for yy in range(sy + sh, min(H, sy + sh + 3)):
            for xx in range(sx, sx + sw):
                if get_px(xx, yy) == g:
                    leaked += 1
        check("no motif bleed below %s" % key, leaked == 0, "%d px" % leaked)
    return foot_bottom


# ---------------- contrast ----------------
def rel_lum(c):
    def lin(v):
        v = v / 255.0
        return v / 12.92 if v <= 0.04045 else ((v + 0.055) / 1.055) ** 2.4
    r, g, b = lin(c[0]), lin(c[1]), lin(c[2])
    return 0.2126 * r + 0.7152 * g + 0.0722 * b


def contrast(c1, c2):
    l1, l2 = rel_lum(c1), rel_lum(c2)
    hi, lo = max(l1, l2), min(l1, l2)
    return (hi + 0.05) / (lo + 0.05)


CONTRAST_PAIRS = [
    ("masthead cream on page", CREAM, PAGE, 15.0),
    ("headline cream on page", CREAM, PAGE, 15.0),
    ("stat gold on page", GOLD, PAGE, 12.0),
    ("caption pale blue-grey on page", PALE, PAGE, 11.0),
    ("brief near-white on page", NEARWHITE, PAGE, 14.0),
    ("brief numeral gold on page", GOLD, PAGE, 12.0),
    ("DATE CHECK cream on red box", CREAM, RED_BOX, 8.0),
    ("banner white on red chip", WHITE, RED_CHIP, 6.8),
    ("footer pale grey on page", FOOT, PAGE, 8.0),
    ("scene border vs page", BORDER, PAGE, 4.9),
]


def contrast_matrix():
    print("CONTRAST MATRIX (measured from render palette)")
    ok_all = True
    for name, fg, bg, minimum in CONTRAST_PAIRS:
        v = contrast(fg, bg)
        ok = v >= minimum
        ok_all = ok_all and ok
        print("  %-34s %5.2f:1  min %4.1f  %s" % (name, v, minimum,
                                                  "PASS" if ok else "FAIL"))
    for tile in TILES:
        v = contrast(CREAM, tile["ground"])
        ok = v >= 8.0
        ok_all = ok_all and ok
        print("  %-34s %5.2f:1  min  8.0  %s" % (
            "tile %s headline cream on ground" % tile["num"], v,
            "PASS" if ok else "FAIL"))
    for r in REGION_ORDER:
        v = contrast(WHITE, REGION_COLORS[r])
        ok = v >= 6.4
        ok_all = ok_all and ok
        print("  %-34s %5.2f:1  min  6.4  %s" % (
            "region %s white on segment" % r, v, "PASS" if ok else "FAIL"))
    check("contrast matrix all pass", ok_all, "")
    return ok_all


def count_color(c, y0, y1):
    n = 0
    for y in range(max(0, y0), min(H, y1)):
        base = y * W * 3
        for x in range(W):
            i = base + x * 3
            if BUF[i] == c[0] and BUF[i + 1] == c[1] and BUF[i + 2] == c[2]:
                n += 1
    return n


def sample_checks():
    my0, my1 = LAYOUT["masthead"]
    check("cream ink in masthead band", count_color(CREAM, my0, my1 + 12) > 500,
          "%d px" % count_color(CREAM, my0, my1 + 12))
    sy0, sy1 = LAYOUT["stats"]
    check("gold ink in stats band", count_color(GOLD, sy0, sy1) > 200, "")
    by0, by1 = LAYOUT["briefs"]
    check("near-white ink in briefs band", count_color(NEARWHITE, by0, by1) > 500, "")
    dy0, dy1 = LAYOUT["date check"]
    check("red box present", count_color(RED_BOX, dy0, dy1) > 5000, "")
    check("cream ink in date check", count_color(CREAM, dy0, dy1) > 200, "")
    check("border colour present", count_color(BORDER, 200, 900) > 1000, "")
    # every scene panel has its 2px border: sample the border rows of each scene
    # (lead scenes + tile scenes) — border pixels must exist on all four sides
    # of every panel; verified by counting BORDER pixels inside each scene rect.
    # (Rects are recorded during render via LAYOUT scene entries below.)
    for key, (x, y, w, h) in SCENE_RECTS.items():
        top = sum(1 for xx in range(x, x + w)
                  if get_px(xx, y) == BORDER or get_px(xx, y + 1) == BORDER)
        check("border top %s" % key, top >= w - 4, "%d/%d" % (top, w))


SCENE_RECTS = {}
SCENE_GROUNDS = {}
LEAD_GROUNDS = {"cyclone": (11, 42, 58), "kyiv": (10, 15, 26),
                "chart": (14, 30, 51)}


# ---------------- PNG (stdlib) ----------------
def write_png(path):
    def chunk(typ, data):
        c = struct.pack(">I", len(data)) + typ + data
        return c + struct.pack(">I", zlib.crc32(typ + data) & 0xFFFFFFFF)

    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
    raw = bytearray()
    for y in range(H):
        raw.append(0)
        raw.extend(BUF[y * W * 3:(y + 1) * W * 3])
    idat = zlib.compress(bytes(raw), 9)
    png = (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr) +
           chunk(b"IDAT", idat) + chunk(b"IEND", b""))
    with open(path, "wb") as f:
        f.write(png)
    # integrity: return the sha256 of the bytes written so the caller can
    # verify the file on disk matches the bytes produced in memory
    return len(png), hashlib.sha256(png).hexdigest()


def main():
    outdir = os.environ.get("MAKEFUN_OUTPUT_DIR") or "."
    os.makedirs(outdir, exist_ok=True)
    before = set(os.listdir(outdir))
    # record scene rects for the border assert (positions mirror render())
    lead_w = (CW - 2 * 8) // 3
    tile_w = (CW - 4 * 8) // 5
    for i, lead in enumerate(LEADS):
        SCENE_RECTS["lead_" + lead["num"]] = (
            MX + i * (lead_w + 8), 208, lead_w, LEAD_SCENE_H)
    # tile scene y positions depend on measured leads_end; recompute roughly:
    # render() records the true ones — fill them in after render via LAYOUT.
    final_y = render()
    contrast_matrix()
    sample_checks()
    out_path = os.path.join(outdir, "entry.png")
    nbytes, digest = write_png(out_path)
    with open(out_path, "rb") as f:
        on_disk = hashlib.sha256(f.read()).hexdigest()
    check("entry.png sha256 matches bytes written", on_disk == digest, digest[:16])
    after = set(os.listdir(outdir))
    new_files = sorted(after - before)
    check("entrypoint wrote ONLY entry.png", new_files == ["entry.png"],
          "new files: %r" % (new_files,))
    print("LAYOUT")
    for k in ("kicker", "masthead", "tagline", "stats", "region bar", "leads",
              "tiles row 1", "tiles row 2", "tiles", "briefs", "date check",
              "footer"):
        if k in LAYOUT:
            print("  %-12s y %4d..%4d" % (k, LAYOUT[k][0], LAYOUT[k][1]))
    print("FINAL_Y %d  (<=1020)" % final_y)
    print("WROTE %s %d bytes" % (out_path, nbytes))
    print("SHA256 %s" % digest)
    print("CHECKS %d passed, 0 failed" % len(CHECKS))
    for name, ok, detail in CHECKS:
        print("  PASS %s %s" % (name, detail))


if __name__ == "__main__":
    main()
